INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('1eb00631-18f7-595b-a059-34038dec117d', 'uk', NULL, 'Дієслово узгоджується з особою: ich bin, du bist, er/sie ist, wir sind, ihr seid.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('1eb00631-18f7-595b-a059-34038dec117d', 'en', NULL, 'The verb matches the person: ich bin, du bist, er/sie ist, wir sind, ihr seid.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('1eb00631-18f7-595b-a059-34038dec117d', 'ru', NULL, 'Глагол согласуется с лицом: ich bin, du bist, er/sie ist, wir sind, ihr seid.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('1eb00631-18f7-595b-a059-34038dec117d', 'tr', NULL, 'Fiil kişiye uyar: ich bin, du bist, er/sie ist, wir sind, ihr seid.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('1eb00631-18f7-595b-a059-34038dec117d', 'de', NULL, 'Das Verb passt zur Person: ich bin, du bist, er/sie ist, wir sind, ihr seid.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('18417b2e-d20c-4317-ac54-9a2e85fdea80', 'ru', 'Im Gegensatz zum Russischen (wo das Verb "sein" im Präsens oft weggelassen wird), muss im Deutschen immer ein Verb stehen: "Ich BIN Nico."', NULL, NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('18417b2e-d20c-4317-ac54-9a2e85fdea80', 'tr', 'Achte auf die Endung. Das Hilfsverb "sein" ist unregelmäßig.', NULL, NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('01b236c3-3b14-5944-a62a-8ce79e418cf0', 'uk', NULL, NULL, 'Дієслово узгоджується з особою: ich bin, du bist, er/sie ist, wir sind, ihr seid.');
