INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('01b236c3-3b14-5944-a62a-8ce79e418cf0', 'ru', NULL, NULL, 'Глагол согласуется с лицом: ich bin, du bist, er/sie ist, wir sind, ihr seid.');
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('01b236c3-3b14-5944-a62a-8ce79e418cf0', 'tr', NULL, NULL, 'Fiil kişiye uyar: ich bin, du bist, er/sie ist, wir sind, ihr seid.');
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('01b236c3-3b14-5944-a62a-8ce79e418cf0', 'de', NULL, NULL, 'Das Verb passt zur Person: ich bin, du bist, er/sie ist, wir sind, ihr seid.');
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('1215d245-1c40-5a33-ac9d-e1418697ae5b', 'uk', NULL, NULL, 'Дієслово узгоджується з особою: ich bin, du bist, er/sie ist, wir sind, ihr seid.');
