INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('1a0bb117-d451-5ba3-ace9-bc5441df9aaa', 'uk', NULL, 'Вчіть кожен іменник разом з його артиклем: der, die або das.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('1a0bb117-d451-5ba3-ace9-bc5441df9aaa', 'en', NULL, 'Learn every noun with its article: der, die, or das.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('1a0bb117-d451-5ba3-ace9-bc5441df9aaa', 'ru', NULL, 'Учите каждое существительное вместе с его артиклем: der, die или das.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('1a0bb117-d451-5ba3-ace9-bc5441df9aaa', 'tr', NULL, 'Her ismi artikeliyle birlikte öğren: der, die veya das.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('1a0bb117-d451-5ba3-ace9-bc5441df9aaa', 'de', NULL, 'Lerne jedes Nomen mit seinem Artikel: der, die oder das.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('5d8277a2-8a1d-574f-abd7-31c0835d19a3', 'de', NULL, 'Lerne jedes Nomen mit seinem Artikel: der, die oder das.', NULL);
