INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('7b937f2b-40e0-403b-b7e4-533ac092fc33', 'ru', 'Im Deutschen ist "Mädchen" sächlich (das), da es ein Diminutiv (-chen) ist, unabhängig vom natürlichen Geschlecht.', NULL, NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('7b937f2b-40e0-403b-b7e4-533ac092fc33', 'tr', 'Im Deutschen haben Nomen ein grammatisches Geschlecht (der/die/das). Wörter auf "-chen" sind immer neutral (das).', NULL, NULL);
