INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('0e321966-c5f5-5066-a7c4-210b81a4a3ee', 'uk', NULL, 'У називному відмінку (Nominativ) «ein» використовується з іменниками чоловічого та середнього роду, а «eine» — жіночого.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('0e321966-c5f5-5066-a7c4-210b81a4a3ee', 'en', NULL, '«Ein» is used for masculine and neuter nouns, «eine» for feminine nouns in the nominative case.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('0e321966-c5f5-5066-a7c4-210b81a4a3ee', 'ru', NULL, 'В именительном падеже (Nominativ) «ein» используется с существительными мужского и среднего рода, а «eine» — женского.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('0e321966-c5f5-5066-a7c4-210b81a4a3ee', 'tr', NULL, 'Yalın halde (Nominativ) eril ve nötr isimlerde «ein», dişil isimlerde «eine» kullanılır.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('0e321966-c5f5-5066-a7c4-210b81a4a3ee', 'de', NULL, 'Ein steht bei maskulinen und neutralen Nomen, eine bei femininen Nomen im Nominativ.', NULL);
