INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('168d5ba3-7022-5893-aac4-2db3c01e5bd0', 'uk', NULL, 'Займенник замінює людину або річ і має узгоджуватися з формою дієслова.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('168d5ba3-7022-5893-aac4-2db3c01e5bd0', 'en', NULL, 'The pronoun replaces a person or thing and must match the verb form.', NULL);
