INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('0b3890af-edcf-5d47-a750-b541cc77c37c', 'uk', NULL, '«Wer» (хто) питає про людей, «wo» (де) про місця, «woher» (звідки) про походження, «wann» (коли) про час.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('0b3890af-edcf-5d47-a750-b541cc77c37c', 'en', NULL, '«Wer» (who) asks about people, «wo» (where) about places, «woher» (where from) about origin, «wann» (when) about time.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('0b3890af-edcf-5d47-a750-b541cc77c37c', 'ru', NULL, '«Wer» (кто) используется для людей, «wo» (где) для мест, «woher» (откуда) для происхождения, «wann» (когда) для времени.', NULL);
