INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('03303919-15ca-5099-a05a-08d8ff6241c3', 'uk', NULL, '«Kein» заперечує іменник з неозначеним артиклем; «nicht» заперечує, серед іншого, прикметники та дієслова.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('03303919-15ca-5099-a05a-08d8ff6241c3', 'en', NULL, '«Kein» negates a noun with an indefinite article; «nicht» negates adjectives and verbs, among other things.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('03303919-15ca-5099-a05a-08d8ff6241c3', 'ru', NULL, '«Kein» отрицает существительное с неопределенным артиклем; «nicht» отрицает, среди прочего, прилагательные и глаголы.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('03303919-15ca-5099-a05a-08d8ff6241c3', 'tr', NULL, '«Kein» belirsiz artikelli bir ismi olumsuz yapar; «nicht» ise sıfatları ve fiilleri olumsuz yapar.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('03303919-15ca-5099-a05a-08d8ff6241c3', 'de', NULL, 'Kein verneint ein Nomen mit unbestimmtem Artikel; nicht verneint unter anderem Adjektive und Verben.', NULL);
