INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('00c03b8e-7035-58c6-a028-e3f574a1fcbd', 'uk', NULL, 'Із зазначенням часу використовується «um», з днями тижня «am»; дієслово узгоджується з підметом.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('00c03b8e-7035-58c6-a028-e3f574a1fcbd', 'en', NULL, 'For times, use «um», for days of the week use «am»; the verb agrees with the subject.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('00c03b8e-7035-58c6-a028-e3f574a1fcbd', 'ru', NULL, 'С указанием времени используется «um», с днями недели «am»; глагол согласуется с подлежащим.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('00c03b8e-7035-58c6-a028-e3f574a1fcbd', 'tr', NULL, 'Saatlerde «um», haftanın günlerinde «am» kullanılır; fiil özneye göre çekimlenir.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('00c03b8e-7035-58c6-a028-e3f574a1fcbd', 'de', NULL, 'Bei Uhrzeiten steht um, bei Wochentagen am; das Verb richtet sich nach dem Subjekt.', NULL);
