INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('332ba820-5446-5a9d-a59d-6ac4b050af05', 'ru', NULL, 'С указанием времени используется «um», с днями недели «am»; глагол согласуется с подлежащим.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('332ba820-5446-5a9d-a59d-6ac4b050af05', 'tr', NULL, 'Saatlerde «um», haftanın günlerinde «am» kullanılır; fiil özneye göre çekimlenir.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('332ba820-5446-5a9d-a59d-6ac4b050af05', 'de', NULL, 'Bei Uhrzeiten steht um, bei Wochentagen am; das Verb richtet sich nach dem Subjekt.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('e28f12a2-601f-50fd-a4ea-69b34f66bd5f', 'de', NULL, NULL, 'Bei Uhrzeiten steht um, bei Wochentagen am; das Verb richtet sich nach dem Subjekt.');
