INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('ba86f33d-39fc-5bb2-a3b9-2c9482a5997a', 'de', NULL, NULL, 'Im Akkusativ wird der/ein zu den/einen; die und das bleiben gleich.');
