INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('0863c8ab-068b-5c02-ab8e-1577559cebe5', 'uk', NULL, NULL, 'Ввічливе прохання з «Sie» починається з інфінітива; форми для «du» та «ihr» коротші.');
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('0863c8ab-068b-5c02-ab8e-1577559cebe5', 'en', NULL, NULL, 'A polite request with «Sie» starts with the infinitive; «du» and «ihr» forms are shorter.');
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('0863c8ab-068b-5c02-ab8e-1577559cebe5', 'ru', NULL, NULL, 'Вежливая просьба с «Sie» начинается с инфинитива; формы для «du» и «ihr» короче.');
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('0863c8ab-068b-5c02-ab8e-1577559cebe5', 'tr', NULL, NULL, '«Sie» ile yapılan kibar bir rica mastarla başlar; «du» ve «ihr» formları ise daha kısadır.');
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('0863c8ab-068b-5c02-ab8e-1577559cebe5', 'de', NULL, NULL, 'Eine höfliche Aufforderung mit Sie beginnt mit dem Infinitiv; du- und ihr-Formen sind kürzer.');
