INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('032a7684-4e63-5ad8-a925-b504bceaf648', 'uk', NULL, '«Wo?» описує місце; «wohin?» описує напрямок. Вчіть сталі вирази разом.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('032a7684-4e63-5ad8-a925-b504bceaf648', 'en', NULL, '«Wo?» describes a place; «wohin?» describes a direction. Learn fixed expressions together.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('032a7684-4e63-5ad8-a925-b504bceaf648', 'ru', NULL, '«Wo?» (Где?) описывает место; «wohin?» (Куда?) описывает направление. Учите устойчивые выражения целиком.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('032a7684-4e63-5ad8-a925-b504bceaf648', 'tr', NULL, '«Wo?» (Nerede?) bir yeri; «wohin?» (Nereye?) ise bir yönü belirtir. Kalıplaşmış ifadeleri bir bütün olarak öğrenin.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('032a7684-4e63-5ad8-a925-b504bceaf648', 'de', NULL, 'Wo? beschreibt einen Ort; wohin? beschreibt eine Richtung. Lerne feste Wendungen zusammen.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('0a268b11-f1da-5beb-a6f5-17163cca1c17', 'uk', NULL, '«Wo?» описує місце; «wohin?» описує напрямок. Вчіть сталі вирази разом.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('0a268b11-f1da-5beb-a6f5-17163cca1c17', 'en', NULL, '«Wo?» describes a place; «wohin?» describes a direction. Learn fixed expressions together.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('ac007d39-040e-5162-a743-4f9da9072a32', 'de', NULL, 'Wo? verlangt Dativ, wohin? verlangt Akkusativ bei in, an, auf, unter und weiteren Wechselpräpositionen.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('0a268b11-f1da-5beb-a6f5-17163cca1c17', 'ru', NULL, '«Wo?» (Где?) описывает место; «wohin?» (Куда?) описывает направление. Учите устойчивые выражения целиком.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('0a268b11-f1da-5beb-a6f5-17163cca1c17', 'tr', NULL, '«Wo?» (Nerede?) bir yeri; «wohin?» (Nereye?) ise bir yönü belirtir. Kalıplaşmış ifadeleri bir bütün olarak öğrenin.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('0a268b11-f1da-5beb-a6f5-17163cca1c17', 'de', NULL, 'Wo? beschreibt einen Ort; wohin? beschreibt eine Richtung. Lerne feste Wendungen zusammen.', NULL);
