INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('1c0ce351-bc5f-5b73-a6ed-36a2515d7c91', 'uk', NULL, 'З прийменниками in, an, auf, unter та іншими запитання «Wo?» вимагає Dativ, а «wohin?» — Akkusativ.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('1c0ce351-bc5f-5b73-a6ed-36a2515d7c91', 'en', NULL, 'With two-way prepositions like in, an, auf, unter, «Wo?» requires the dative, and «wohin?» requires the accusative.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('1c0ce351-bc5f-5b73-a6ed-36a2515d7c91', 'ru', NULL, 'С предлогами in, an, auf, unter и другими вопросом «Wo?» требуется Dativ, а с вопросом «wohin?» — Akkusativ.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('1c0ce351-bc5f-5b73-a6ed-36a2515d7c91', 'tr', NULL, 'in, an, auf, unter gibi yön bildiren edatlarda «Wo?» sorusu Dativ, «wohin?» sorusu Akkusativ gerektirir.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('1c0ce351-bc5f-5b73-a6ed-36a2515d7c91', 'de', NULL, 'Wo? verlangt Dativ, wohin? verlangt Akkusativ bei in, an, auf, unter und weiteren Wechselpräpositionen.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('dc25139e-ae1d-5d24-a3c6-c616baa5656a', 'de', NULL, 'Wo? verlangt Dativ, wohin? verlangt Akkusativ bei in, an, auf, unter und weiteren Wechselpräpositionen.', NULL);
