INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('a991c2f5-050a-5c34-ac36-9a5ae69da867', 'de', NULL, 'Seit beschreibt einen Beginn bis heute, vor einen Zeitpunkt in der Vergangenheit und für eine Dauer.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('c42024c6-44c7-5160-ad2b-37862a221278', 'de', NULL, 'Seit beschreibt einen Beginn bis heute, vor einen Zeitpunkt in der Vergangenheit und für eine Dauer.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('2fee1455-8f8b-5eaf-a3e5-5ce93670ec93', 'uk', NULL, NULL, '«Seit» вказує на початок дії, що триває досі, «vor» на момент у минулому, а «für» на тривалість.');
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('2fee1455-8f8b-5eaf-a3e5-5ce93670ec93', 'en', NULL, NULL, '«Seit» describes a beginning until today, «vor» a point in time in the past, and «für» a duration.');
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('2fee1455-8f8b-5eaf-a3e5-5ce93670ec93', 'ru', NULL, NULL, '«Seit» указывает на начало действия, длящегося до сих пор, «vor» на момент в прошлом, а «für» на продолжительность.');
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('2fee1455-8f8b-5eaf-a3e5-5ce93670ec93', 'tr', NULL, NULL, '«Seit» bugüne kadar devam eden bir başlangıcı, «vor» geçmişteki bir anı, «für» ise bir süreyi ifade eder.');
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('2fee1455-8f8b-5eaf-a3e5-5ce93670ec93', 'de', NULL, NULL, 'Seit beschreibt einen Beginn bis heute, vor einen Zeitpunkt in der Vergangenheit und für eine Dauer.');
