INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('031bb6a6-a8dc-52ce-a68c-b0917c0f65dc', 'uk', NULL, '«Als» описує одноразову подію в минулому, «wenn» — повторювані події або умови.', NULL);
