INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('031bb6a6-a8dc-52ce-a68c-b0917c0f65dc', 'tr', NULL, '«Als» geçmişteki tek seferlik bir olayı tanımlarken, «wenn» tekrarlanan olayları veya koşulları tanımlar.', NULL);
