INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('2292593a-43d6-5b08-a4f4-a164cca9943e', 'de', NULL, 'Als beschreibt ein einmaliges Ereignis in der Vergangenheit, wenn Wiederholungen oder Bedingungen.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('3096f3c6-b2b4-5aee-a22b-4da0def6a6fe', 'uk', NULL, '«Als» описує одноразову подію в минулому, «wenn» — повторювані події або умови.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('3096f3c6-b2b4-5aee-a22b-4da0def6a6fe', 'en', NULL, '«Als» describes a single event in the past, «wenn» describes repetitions or conditions.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('3096f3c6-b2b4-5aee-a22b-4da0def6a6fe', 'ru', NULL, '«Als» описывает однократное событие в прошлом, «wenn» — повторяющиеся события или условия.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('3096f3c6-b2b4-5aee-a22b-4da0def6a6fe', 'tr', NULL, '«Als» geçmişteki tek seferlik bir olayı tanımlarken, «wenn» tekrarlanan olayları veya koşulları tanımlar.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('3096f3c6-b2b4-5aee-a22b-4da0def6a6fe', 'de', NULL, 'Als beschreibt ein einmaliges Ereignis in der Vergangenheit, wenn Wiederholungen oder Bedingungen.', NULL);
