INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('0298a74d-2b63-5e4d-aee3-66b456b3c119', 'uk', NULL, 'Форми «könnte», «hätte», «wäre» та «würde» роблять прохання та побажання більш ввічливими.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('0298a74d-2b63-5e4d-aee3-66b456b3c119', 'en', NULL, 'The forms «könnte», «hätte», «wäre», and «würde» make requests and wishes more polite.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('0298a74d-2b63-5e4d-aee3-66b456b3c119', 'ru', NULL, 'Формы «könnte», «hätte», «wäre» и «würde» делают просьбы и пожелания более вежливыми.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('0298a74d-2b63-5e4d-aee3-66b456b3c119', 'tr', NULL, '«könnte», «hätte», «wäre» ve «würde» formları ricaları ve dilekleri daha kibar hale getirir.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('0298a74d-2b63-5e4d-aee3-66b456b3c119', 'de', NULL, 'Könnte, hätte, wäre und würde machen Bitten und Wünsche höflicher.', NULL);
