INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('0ba2ba0d-8d67-5306-aee4-d8a64b476c93', 'uk', NULL, 'Після «ob» або питального слова дієслово стоїть у кінці непрямого питання.', NULL);
