INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('1ea75b54-210e-5ea2-a406-0a5301a498ca', 'uk', NULL, '«Und», «aber», «denn» і «oder» з''єднують головні речення; після «weil» дієслово стоїть у кінці.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('1ea75b54-210e-5ea2-a406-0a5301a498ca', 'en', NULL, '«Und», «aber», «denn», and «oder» connect main clauses; after «weil» the verb goes at the end.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('1ea75b54-210e-5ea2-a406-0a5301a498ca', 'ru', NULL, '«Und», «aber», «denn» и «oder» соединяют главные предложения; после «weil» глагол стоит в конце.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('1ea75b54-210e-5ea2-a406-0a5301a498ca', 'tr', NULL, '«Und», «aber», «denn» ve «oder» ana cümleleri bağlar; «weil» den sonra fiil en sonda yer alır.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('1ea75b54-210e-5ea2-a406-0a5301a498ca', 'de', NULL, 'Und, aber, denn und oder verbinden Hauptsätze; nach weil steht das Verb am Ende.', NULL);
