INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('0a95f820-f205-5c57-a820-cb0337887c79', 'uk', NULL, '«Um zu» використовується при одному й тому ж підметі; «damit» дозволяє використовувати різні підмети.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('0a95f820-f205-5c57-a820-cb0337887c79', 'en', NULL, 'Use «um zu» with the same subject; «damit» allows different subjects.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('0a95f820-f205-5c57-a820-cb0337887c79', 'ru', NULL, '«Um zu» используется при одном и том же подлежащем; «damit» позволяет использовать разные подлежащие.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('0a95f820-f205-5c57-a820-cb0337887c79', 'tr', NULL, '«Um zu» aynı özneyle kullanılır; «damit» ise farklı öznelere izin verir.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('0a95f820-f205-5c57-a820-cb0337887c79', 'de', NULL, 'Um zu verwendet man bei gleichem Subjekt; damit erlaubt unterschiedliche Subjekte.', NULL);
