INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('042fa22d-25c4-54ee-a808-f8ff99d3dd98', 'uk', NULL, NULL, '«Obwohl» починає підрядне речення; після «trotzdem» йде головне речення з дієсловом на другому місці.');
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('856a2268-a104-5a05-ae2b-1449064fe96b', 'de', NULL, 'Da(r)- und wo(r)- ersetzen Präpositionen mit Sachen; vor Vokalen steht r.', NULL);
