INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('042fa22d-25c4-54ee-a808-f8ff99d3dd98', 'ru', NULL, NULL, '«Obwohl» начинает придаточное предложение; после «trotzdem» следует главное предложение с глаголом на втором месте.');
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('042fa22d-25c4-54ee-a808-f8ff99d3dd98', 'tr', NULL, NULL, '«Obwohl» bir yan cümleyi başlatır; «trotzdem» kelimesinden sonra fiilin ikinci sırada olduğu bir ana cümle gelir.');
