INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('27bd2074-b995-5101-a2a0-4d3302900f5a', 'uk', NULL, 'Після «lassen» йде інфінітив без «zu»; заперечне «brauchen» в літературній мові використовується з «zu».', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('27bd2074-b995-5101-a2a0-4d3302900f5a', 'en', NULL, 'After «lassen», use an infinitive without «zu»; the negated form of «brauchen» is used with «zu» in standard German.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('27bd2074-b995-5101-a2a0-4d3302900f5a', 'ru', NULL, 'После «lassen» следует инфинитив без «zu»; отрицательное «brauchen» в литературном языке используется с «zu».', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('27bd2074-b995-5101-a2a0-4d3302900f5a', 'tr', NULL, '«lassen» fiilinden sonra «zu» olmadan mastar (infinitiv) kullanılır; olumsuz yapılan «brauchen» standart dilde «zu» ile kullanılır.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('27bd2074-b995-5101-a2a0-4d3302900f5a', 'de', NULL, 'Nach lassen steht ein Infinitiv ohne zu; verneintes brauchen wird standardsprachlich mit zu verwendet.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('9c531439-58d4-552f-a562-e67b9c8567a5', 'de', NULL, 'Nach lassen steht ein Infinitiv ohne zu; verneintes brauchen wird standardsprachlich mit zu verwendet.', NULL);
