INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('162a19bf-8b08-515f-a0da-5683435f03bc', 'uk', NULL, 'Plusquamperfekt (давноминулий час) описує більш ранню з двох дій у минулому: hatte/war + Partizip.', NULL);
