INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('15fa5353-201a-5b29-ac19-ba7c85b80308', 'uk', NULL, NULL, 'При однаковому підметі використовуються «ohne zu» і «anstatt zu» з інфінітивом; при різних підметах використовується «ohne dass».');
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('15fa5353-201a-5b29-ac19-ba7c85b80308', 'en', NULL, NULL, 'With the same subject, use «ohne zu» and «anstatt zu» with an infinitive; with a different subject, use «ohne dass».');
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('15fa5353-201a-5b29-ac19-ba7c85b80308', 'ru', NULL, NULL, 'При одинаковом подлежащем используются «ohne zu» и «anstatt zu» с инфинитивом; при разных подлежащих используется «ohne dass».');
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('15fa5353-201a-5b29-ac19-ba7c85b80308', 'tr', NULL, NULL, 'Aynı özne olduğunda «ohne zu» ve «anstatt zu» mastarla kullanılır; farklı özne olduğunda «ohne dass» kullanılır.');
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('15fa5353-201a-5b29-ac19-ba7c85b80308', 'de', NULL, NULL, 'Bei gleichem Subjekt stehen ohne zu und anstatt zu mit Infinitiv; bei anderem Subjekt verwendet man ohne dass.');
