INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('151569f7-7391-5aa3-a887-f3b162de8417', 'uk', NULL, NULL, '«Seitdem» описує початок, «bis» — кінцеву точку, а «sobald» — безпосередньо наступний момент.');
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('151569f7-7391-5aa3-a887-f3b162de8417', 'en', NULL, NULL, '«Seitdem» describes a beginning, «bis» an endpoint, and «sobald» the immediately following moment.');
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('151569f7-7391-5aa3-a887-f3b162de8417', 'ru', NULL, NULL, '«Seitdem» описывает начало, «bis» — конечную точку, а «sobald» — непосредственно следующий момент.');
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('151569f7-7391-5aa3-a887-f3b162de8417', 'tr', NULL, NULL, '«Seitdem» bir başlangıcı, «bis» bir bitiş noktasını, «sobald» ise hemen ardından gelen anı ifade eder.');
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('151569f7-7391-5aa3-a887-f3b162de8417', 'de', NULL, NULL, 'Seitdem beschreibt einen Beginn, bis einen Endpunkt und sobald den unmittelbar folgenden Zeitpunkt.');
