INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('1f1f67b9-7347-5511-a39c-ae2e105caa03', 'uk', NULL, 'У головному реченні відмінюване дієслово стоїть на другій позиції; у підрядному — в кінці. Займенники зазвичай стоять перед іменниковими додатками.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('1f1f67b9-7347-5511-a39c-ae2e105caa03', 'en', NULL, 'In the main clause, the finite verb is in position two; in the subordinate clause, at the end. Pronouns usually come before noun objects.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('1f1f67b9-7347-5511-a39c-ae2e105caa03', 'ru', NULL, 'В главном предложении спрягаемый глагол стоит на втором месте; в придаточном — в конце. Местоимения обычно стоят перед дополнениями-существительными.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('1f1f67b9-7347-5511-a39c-ae2e105caa03', 'tr', NULL, 'Ana cümlede çekimli fiil ikinci sıradadır; yan cümlede ise en sondadır. Zamirler genellikle isim nesnelerinden önce gelir.', NULL);
INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('1f1f67b9-7347-5511-a39c-ae2e105caa03', 'de', NULL, 'Im Hauptsatz steht das finite Verb an Position zwei; im Nebensatz am Ende. Pronomen stehen meist vor Nomenobjekten.', NULL);
