INSERT INTO public.grammar_translations (exercise_id, locale, hint, smart_hint, explanation) VALUES ('05aa0367-e456-51f8-a422-c5a05973d44b', 'uk', NULL, 'Офіційні листи вимагають чітких зв''язків між реченнями, ввічливих форм і правильних відмінків.', NULL);
