INSERT INTO public.learning_reading_texts (id, legacy_cefr_level, sentence_de, focus, audio_url, created_at, unit_id) VALUES ('aff05e3f-6a15-4917-a410-72c5643058a6', 'B2', 'Ich würde vorschlagen, die Entscheidung um eine Woche zu verschieben.', 'sch, ie', NULL, '2026-09-06 11:51:33.102824+00', NULL);
INSERT INTO public.learning_reading_texts (id, legacy_cefr_level, sentence_de, focus, audio_url, created_at, unit_id) VALUES ('b0bab2ca-6bac-4b33-8885-77ace08ffd63', 'B2', 'Man sollte nicht voreilig urteilen, bevor alle Fakten vorliegen.', 'ei, g', NULL, '2026-09-06 11:51:33.102824+00', NULL);
INSERT INTO public.learning_reading_texts (id, legacy_cefr_level, sentence_de, focus, audio_url, created_at, unit_id) VALUES ('d3c6cbd5-9d97-4ad2-8864-3149fdf7fb14', 'B2', 'Inzwischen hat sich die Lage deutlich entspannt.', 'z, sch', NULL, '2026-09-06 11:51:33.102824+00', NULL);
INSERT INTO public.learning_reading_texts (id, legacy_cefr_level, sentence_de, focus, audio_url, created_at, unit_id) VALUES ('e5430265-9f1e-428b-ba02-1feeab45a054', 'C1', 'Ungeachtet aller Einwände bleibt die Kernaussage überzeugend.', 'ä, z', NULL, '2026-09-06 11:51:33.102824+00', NULL);
INSERT INTO public.learning_reading_texts (id, legacy_cefr_level, sentence_de, focus, audio_url, created_at, unit_id) VALUES ('b83bd6de-60fe-4a20-9c5f-91caf4def76b', 'C1', 'Die Ironie lag weniger im Inhalt als im Tonfall.', 'ie, f', NULL, '2026-09-06 11:51:33.102824+00', NULL);
INSERT INTO public.learning_reading_texts (id, legacy_cefr_level, sentence_de, focus, audio_url, created_at, unit_id) VALUES ('cad4b4c0-6b60-4948-aa99-0f628f305ce2', 'C2', 'Selbst flüchtige Alliterationen können einem Satz Gewicht verleihen.', 'fl, tz', NULL, '2026-09-06 11:51:33.102824+00', NULL);
INSERT INTO public.learning_reading_texts (id, legacy_cefr_level, sentence_de, focus, audio_url, created_at, unit_id) VALUES ('e6ebfb7b-aafc-4321-ac9b-416d61be8117', 'C2', 'Die Prosodie verrät oft mehr als die gewählten Lexeme.', 's, ie', NULL, '2026-09-06 11:51:33.102824+00', NULL);
INSERT INTO public.learning_reading_texts (id, legacy_cefr_level, sentence_de, focus, audio_url, created_at, unit_id) VALUES ('f26bbe79-3ba6-421d-ada2-14f03e3e45ce', 'C2', 'Sprachliche Eleganz entsteht, wo Präzision und Rhythmus einander tragen.', 'z, ch', NULL, '2026-09-06 11:51:33.102824+00', NULL);
INSERT INTO public.learning_reading_texts (id, legacy_cefr_level, sentence_de, focus, audio_url, created_at, unit_id) VALUES ('c1fb80e4-0774-45e0-8513-962b45038d2d', 'C1', 'Die Prosodie trägt oft mehr Bedeutung als das einzelne Lexem.', 's, ie', NULL, '2026-09-06 14:55:59.655345+00', NULL);
INSERT INTO public.learning_reading_texts (id, legacy_cefr_level, sentence_de, focus, audio_url, created_at, unit_id) VALUES ('a71b44a1-cb3a-4f52-b4eb-07473e63899b', 'C2', 'Die Kunst liegt darin, schwere Laute leicht und leichte Laute gewichtig zu sprechen.', 'ch, ei', NULL, '2026-09-06 14:55:59.655345+00', NULL);
INSERT INTO public.learning_reading_texts (id, legacy_cefr_level, sentence_de, focus, audio_url, created_at, unit_id) VALUES ('d249edce-1c7e-4538-900d-f4d19306ae58', 'B2', 'Die Betonung verschiebt die Bedeutung oft um eine ganze Nuance.', 'ö, z', NULL, '2026-09-06 14:55:59.655345+00', NULL);
INSERT INTO public.learning_reading_texts (id, legacy_cefr_level, sentence_de, focus, audio_url, created_at, unit_id) VALUES ('d971f7a0-ec5a-4f3b-bccb-f00ae63bb117', 'B2', 'Wer bewusst artikuliert, wird auch in schwierigen Sätzen verstanden.', 'z, ch', NULL, '2026-09-06 14:55:59.655345+00', NULL);
INSERT INTO public.learning_reading_texts (id, legacy_cefr_level, sentence_de, focus, audio_url, created_at, unit_id) VALUES ('2bd081e1-bae3-4c4f-870c-6c4c3548bf72', 'C1', 'Wer Widersprüche aushält, gewinnt an sprachlicher Souveränität.', 'ch, ä', NULL, '2026-09-06 11:51:33.102824+00', NULL);
INSERT INTO public.learning_reading_texts (id, legacy_cefr_level, sentence_de, focus, audio_url, created_at, unit_id) VALUES ('2ce832d8-6380-4de4-a890-854fa8ea4ede', 'B2', 'Die Diskussion hat gezeigt, dass beide Seiten berechtigte Einwände haben.', 'sch, ä', NULL, '2026-09-06 11:51:33.102824+00', NULL);
INSERT INTO public.learning_reading_texts (id, legacy_cefr_level, sentence_de, focus, audio_url, created_at, unit_id) VALUES ('424d0372-11ad-4e97-ac5f-58cb96193db4', 'C1', 'Es bedarf einer differenzierten Betrachtung, um vorschnelle Schlüsse zu vermeiden.', 'z, sch', NULL, '2026-09-06 11:51:33.102824+00', NULL);
INSERT INTO public.learning_reading_texts (id, legacy_cefr_level, sentence_de, focus, audio_url, created_at, unit_id) VALUES ('456ac6dd-0a9a-4549-a5ae-9472d49166d0', 'B2', 'Der Vortrag war zwar anspruchsvoll, aber äußerst lehrreich.', 'äu, ch', NULL, '2026-09-06 11:51:33.102824+00', NULL);
INSERT INTO public.learning_reading_texts (id, legacy_cefr_level, sentence_de, focus, audio_url, created_at, unit_id) VALUES ('4c27f103-769a-4461-ada9-8e3382a7a842', 'C1', 'Die Nuancen der deutschen Satzmelodie entscheiden über Höflichkeit und Distanz.', 'z, ch', NULL, '2026-09-06 11:51:33.102824+00', NULL);
INSERT INTO public.learning_reading_texts (id, legacy_cefr_level, sentence_de, focus, audio_url, created_at, unit_id) VALUES ('5ed1b469-33a6-40e6-ac9c-db6fa54eaf07', 'B2', 'Es kommt darauf an, wie gründlich man sich vorbereitet.', 'ü, ch', NULL, '2026-09-06 11:51:33.102824+00', NULL);
INSERT INTO public.learning_reading_texts (id, legacy_cefr_level, sentence_de, focus, audio_url, created_at, unit_id) VALUES ('622150d7-250d-4dac-bdf3-a932636ae0f1', 'C1', 'Sie argumentierte schlüssig, ohne den Gegenüber bloßzustellen.', 'sch, ü', NULL, '2026-09-06 11:51:33.102824+00', NULL);
INSERT INTO public.learning_reading_texts (id, legacy_cefr_level, sentence_de, focus, audio_url, created_at, unit_id) VALUES ('65f3ddae-71fe-47a2-867c-454c4a8e0411', 'C2', 'Wer Stil beherrscht, kann auch Schweigen beredt machen.', 'sch, ch', NULL, '2026-09-06 11:51:33.102824+00', NULL);
INSERT INTO public.learning_reading_texts (id, legacy_cefr_level, sentence_de, focus, audio_url, created_at, unit_id) VALUES ('6f6d08ed-0452-43e5-ba44-70c8cae98fb3', 'C2', 'Nur wer die Satzmelodie beherrscht, klingt wirklich idiomatisch.', 'ch, t', NULL, '2026-09-06 14:55:59.655345+00', NULL);
