INSERT INTO public.learning_reading_texts (id, legacy_cefr_level, sentence_de, focus, audio_url, created_at, unit_id) VALUES ('9679e3bb-a8cb-438f-8873-9ce61fadd39a', 'C1', 'Ein präziser Wortschatz ersetzt mitunter ganze Erklärungen.', 'z, ch', NULL, '2026-09-06 11:51:33.102824+00', NULL);
