INSERT INTO public.learning_reading_texts (id, legacy_cefr_level, sentence_de, focus, audio_url, created_at, unit_id) VALUES ('86e3f4b3-74b9-4fcd-8e88-b21b6e6a160f', NULL, 'Ich bin müde.', 'ü', NULL, '2026-09-06 14:55:59.655345+00', '86e3f4b3-74b9-4fcd-8e88-b21b6e6a160f');
