INSERT INTO public.learning_reading_texts (id, legacy_cefr_level, sentence_de, focus, audio_url, created_at, unit_id) VALUES ('933fdedf-8855-48c8-8d51-5177f96dbbab', NULL, 'Ich versuche, jeden Tag ein bisschen Deutsch zu sprechen.', 'ch, ü', NULL, '2026-09-06 14:55:59.655345+00', '933fdedf-8855-48c8-8d51-5177f96dbbab');
