INSERT INTO public.learning_reading_texts (id, legacy_cefr_level, sentence_de, focus, audio_url, created_at, unit_id) VALUES ('b73f6228-c6c7-591b-ac83-2bae82a3b163', NULL, 'Ich wohne in der Gartenstraße. Meine Nachbarin heißt Leyla. Sie ist neu hier. Heute treffen wir uns vor dem Haus. Ich sage Hallo und frage: Wie geht es Ihnen? Leyla lächelt. Es geht ihr gut. Wir trinken später zusammen Kaffee.', 'ei und eu; Fragen', NULL, '2026-09-10 18:50:12.118558+00', 'b73f6228-c6c7-591b-ac83-2bae82a3b163');
