INSERT INTO public.vocabulary_translations (card_id, locale, translation, context_sentence, is_difficult) VALUES ('b2d93634-5099-4b7d-8ddb-e62765d70245', 'de', NULL, 'Wie alt bist du? Ich bin 20 Jahre alt.', false);
