INSERT INTO public.vocabulary_translations (card_id, locale, translation, context_sentence, is_difficult) VALUES ('b3ec422c-cb54-4cd3-894d-ed281dfc26cc', 'de', NULL, 'Wie geht es Ihnen? Danke, gut.', false);
